     "time": "10-01 10:00",
     "ts": 1790820017,
     "summary": "日本央行在上个月的政策会议纪要中确认，其政策重点已转向防止通胀超过目标水平。在此会议上，该行将政策利率上调至1995年以来最高水平。该纪要可能进一步强化市场对日本央行今年将再次加息的预期。在会议纪要公布前，掉期市场显示，交易员认为日本央行在12月底之前再次加息的概率超过95%，而在央行10月30日下一次政策会议上加息的概率约为21%。（文章来源：财联社）",
